import sys
input = sys.stdin.readline

def suffix_array(s):
    n = len(s)
    m = n + 130
    rank = [ord(c) for c in s]
    sa = list(range(n))
    k = 1
    while True:
        key = [(rank[i] + 1) * m + (rank[i + k] + 1 if i + k < n else 0) for i in range(n)]
        sa.sort(key=key.__getitem__)
        new = [0] * n
        for j in range(1, n):
            new[sa[j]] = new[sa[j - 1]] + (1 if key[sa[j]] != key[sa[j - 1]] else 0)
        rank = new
        if rank[sa[n - 1]] == n - 1:
            break
        k *= 2
    return sa

def lcp_array(s, sa):
    n = len(s)
    rk = [0] * n
    for i in range(n):
        rk[sa[i]] = i
    lcp = [0] * n
    h = 0
    for i in range(n):
        if rk[i] > 0:
            j = sa[rk[i] - 1]
            while i + h < n and j + h < n and s[i + h] == s[j + h]:
                h += 1
            lcp[rk[i]] = h
            if h > 0:
                h -= 1
        else:
            h = 0
    return lcp

