#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

vector<int> suffixArray(const string& s) {
    int n = (int)s.size();
    long long m = n + 130;
    vector<long long> rk(n), key(n), nr(n);
    vector<int> sa(n);
    for (int i = 0; i < n; i++) {
        rk[i] = (unsigned char)s[i];
        sa[i] = i;
    }
    for (int k = 1;; k *= 2) {
        for (int i = 0; i < n; i++) key[i] = (rk[i] + 1) * m + (i + k < n ? rk[i + k] + 1 : 0);
        sort(sa.begin(), sa.end(), [&](int a, int b) { return key[a] < key[b]; });
        nr[sa[0]] = 0;
        for (int j = 1; j < n; j++) nr[sa[j]] = nr[sa[j - 1]] + (key[sa[j]] != key[sa[j - 1]] ? 1 : 0);
        rk = nr;
        if (rk[sa[n - 1]] == n - 1) break;
    }
    return sa;
}

vector<int> lcpArray(const string& s, const vector<int>& sa) {
    int n = (int)s.size();
    vector<int> rk(n), lcp(n, 0);
    for (int i = 0; i < n; i++) rk[sa[i]] = i;
    int h = 0;
    for (int i = 0; i < n; i++) {
        if (rk[i] > 0) {
            int j = sa[rk[i] - 1];
            while (i + h < n && j + h < n && s[i + h] == s[j + h]) h++;
            lcp[rk[i]] = h;
            if (h > 0) h--;
        } else {
            h = 0;
        }
    }
    return lcp;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;
    long long k;
    cin >> k;

    long long len = s.size();
    if (k == 1) {
        cout << len << "\n";
    } else if (k > len) {
        cout << 0 << "\n";
    } else {
        vector<int> sa = suffixArray(s);
        vector<int> lcp = lcpArray(s, sa);
        long long w = k - 1;
        int best = 0;
        vector<int> dq(len);
        int head = 0, tail = 0;
        for (int i = 1; i < len; i++) {
            while (tail > head && lcp[dq[tail - 1]] >= lcp[i]) tail--;
            dq[tail++] = i;
            if (dq[head] <= i - w) head++;
            if (i >= w && lcp[dq[head]] > best) best = lcp[dq[head]];
        }
        cout << best << "\n";
    }

    return 0;
}

