import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] suffixArray(String s) {
        int n = s.length();
        long m = n + 130;
        int[] rk = new int[n];
        int[] nr = new int[n];
        int[] sa = new int[n];
        long[] packed = new long[n];
        for (int i = 0; i < n; i++) rk[i] = s.charAt(i);
        for (int k = 1; ; k *= 2) {
            for (int i = 0; i < n; i++) {
                long key = (rk[i] + 1) * m + (i + k < n ? rk[i + k] + 1 : 0);
                packed[i] = (key << 15) | i;
            }
            Arrays.sort(packed);
            for (int j = 0; j < n; j++) sa[j] = (int) (packed[j] & 32767);
            nr[sa[0]] = 0;
            for (int j = 1; j < n; j++) nr[sa[j]] = nr[sa[j - 1]] + ((packed[j] >> 15) != (packed[j - 1] >> 15) ? 1 : 0);
            int[] t = rk;
            rk = nr;
            nr = t;
            if (rk[sa[n - 1]] == n - 1) break;
        }
        return sa;
    }

    static int[] lcpArray(String s, int[] sa) {
        int n = s.length();
        int[] rk = new int[n];
        int[] lcp = new int[n];
        for (int i = 0; i < n; i++) rk[sa[i]] = i;
        int h = 0;
        for (int i = 0; i < n; i++) {
            if (rk[i] > 0) {
                int j = sa[rk[i] - 1];
                while (i + h < n && j + h < n && s.charAt(i + h) == s.charAt(j + h)) h++;
                lcp[rk[i]] = h;
                if (h > 0) h--;
            } else {
                h = 0;
            }
        }
        return lcp;
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        long k = Long.parseLong(next());

        int len = s.length();
        if (k == 1) {
            System.out.println(len);
        } else if (k > len) {
            System.out.println(0);
        } else {
            int[] sa = suffixArray(s);
            int[] lcp = lcpArray(s, sa);
            int w = (int) k - 1;
            int best = 0;
            int[] dq = new int[len];
            int head = 0, tail = 0;
            for (int i = 1; i < len; i++) {
                while (tail > head && lcp[dq[tail - 1]] >= lcp[i]) tail--;
                dq[tail++] = i;
                if (dq[head] <= i - w) head++;
                if (i >= w && lcp[dq[head]] > best) best = lcp[dq[head]];
            }
            System.out.println(best);
        }
    }
}
